// Guardrail Ebene 3 (v03, 10.11.2026): harte Ausgabe-Pruefung vor der Antwort an den Menschen.
// Warum: ein Agent darf nichts melden, was kein Werkzeug belegt. Fehlertexte sind fest, die Funde stehen nur als Codes im Feld funde (kein Muster- und Modellfeld-Leck).
// v04 (10.11.2026): die Beobachtung eines Werkzeugs hat das echte Format [{"antwort":"STATUS: OK ..."}] (stringifiziertes Array, gemessen in Lauf 2593), nicht den Rohtext; sie wird vor dem Vergleich entpackt. Recherche: 1 Aufruf, eine Wiederholung nur nach FEHLER (wie Prompt und Sub: höchstens 2).
const item = $input.first().json;
const cfg = $('Konfiguration [Edit Fields]').first().json;
const roh = String(item.output ?? '');
const funde = [];
let daten = null;
const treffer = roh.match(/\{[\s\S]*\}/);
try { daten = treffer ? JSON.parse(treffer[0]) : null; } catch (e) { daten = null; }
if (!daten || typeof daten !== 'object' || Array.isArray(daten)) { funde.push('JSON_UNGUELTIG'); daten = null; }

// Beobachtung: was die Werkzeuge wirklich geliefert haben (aus den Zwischenschritten, nicht aus der Selbstauskunft des Agenten)
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
// Beobachtung entpacken: echtes Format ist ein JSON-Text mit Array von Objekten und dem Feld antwort; sonst gilt der Rohtext
const entpacke = (o) => {
  let v = o;
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return v; } }
  const liste = Array.isArray(v) ? v : [v];
  return liste.map(x => (x && typeof x === 'object') ? (typeof x.antwort === 'string' ? x.antwort : JSON.stringify(x)) : String(x ?? '')).join('\n');
};
const aufrufe = steps.map(s => ({ tool: String((s && s.action && s.action.tool) || '?'), obs: entpacke(s && s.observation) }));
const schritte = aufrufe.map(a => a.tool);
const BEKANNT = ['Markenwissen_abfragen', 'Thema_recherchieren', 'Text_schreiben', 'Bilder_gestalten', 'Zur_Freigabe_einreichen'];
if (schritte.length > 8) funde.push('ZU_VIELE_AUFRUFE');
const recherchen = aufrufe.filter(a => a.tool === 'Thema_recherchieren');
// 1 Recherche, eine Wiederholung nur wenn der erste Aufruf FEHLER meldete (nicht nach NICHT_GEFUNDEN oder STATUS: OK); mehr nie
if (recherchen.length > 2 || (recherchen.length === 2 && !/^\s*FEHLER/.test(recherchen[0].obs))) funde.push('RECHERCHE_MEHRFACH');
if (schritte.some(t => !BEKANNT.includes(t))) funde.push('UNBEKANNTES_WERKZEUG');

const erlaubt = ['eingereicht', 'abgelehnt', 'rueckfrage', 'fehler'];
let hinweis = '', rueckfrage = '', postId = '';
if (daten) {
  // Feldtypen: Pflichtfelder sind Zeichenketten, optionale Felder Zeichenkette oder leer
  for (const f of ['prompt_version', 'status', 'hinweis_an_mensch', 'toolentscheidung']) {
    if (!(f in daten)) funde.push('FELD_FEHLT:' + f);
    else if (typeof daten[f] !== 'string') funde.push('FELDTYP:' + f);
  }
  for (const f of ['post_id', 'rueckfrage']) {
    if (f in daten && daten[f] !== null && typeof daten[f] !== 'string') funde.push('FELDTYP:' + f);
  }
  hinweis = typeof daten.hinweis_an_mensch === 'string' ? daten.hinweis_an_mensch : '';
  rueckfrage = typeof daten.rueckfrage === 'string' ? daten.rueckfrage : '';
  postId = typeof daten.post_id === 'string' ? daten.post_id.trim() : '';
  if (typeof daten.status === 'string' && !erlaubt.includes(daten.status)) funde.push('STATUS_UNBEKANNT');
  if (typeof daten.prompt_version === 'string' && daten.prompt_version !== cfg.prompt_version) funde.push('PROMPT_VERSION_ABWEICHEND');
  if (hinweis.length > 400) funde.push('HINWEIS_ZU_LANG');
  if (rueckfrage.length > 300) funde.push('RUECKFRAGE_ZU_LANG');
  // H1: kein Erfolg ohne beobachtete post_id. Die post_id muss in der Rueckgabe von Zur_Freigabe_einreichen stehen (STATUS: OK, genau 1 Aufruf).
  const einreich = aufrufe.filter(a => a.tool === 'Zur_Freigabe_einreichen');
  const einreichOk = einreich.filter(a => /^\s*STATUS:\s*OK/.test(a.obs));
  if (daten.status === 'eingereicht') {
    if (!postId) funde.push('EINGEREICHT_OHNE_POST_ID');
    else if (einreich.length !== 1) funde.push('EINGEREICHT_OHNE_BEOBACHTUNG');
    else if (einreichOk.length !== 1 || postId.length < 8 || !einreichOk[0].obs.includes(postId)) funde.push('POST_ID_NICHT_BEOBACHTET');
  } else {
    if (postId) funde.push('POST_ID_OHNE_EINREICHUNG');
    if (einreichOk.length > 0) funde.push('EINREICHUNG_NICHT_GEMELDET');
    if (daten.status === 'rueckfrage' && !rueckfrage.trim()) funde.push('RUECKFRAGE_LEER');
  }
}

// M2: Muster. Schluessel und Tokens prueft die ganze Antwort, interne Namen und Prompt-Reste die fuer Menschen sichtbaren Felder.
const GEHEIM = [/sk-[A-Za-z0-9_-]{10,}/, /nvapi-/i, /eyJ[A-Za-z0-9_-]{10,}/, /sb_secret_/i, /pplx-[A-Za-z0-9]/i, /Bearer\s+[A-Za-z0-9._-]{8,}/i];
for (let i = 0; i < GEHEIM.length; i++) { if (GEHEIM[i].test(roh)) funde.push('MUSTER_GEHEIM:' + i); }
const sichtbar = hinweis + '\n' + rueckfrage + '\n' + postId;
const INTERN = [
  /k1_[a-z_]+|k2_[a-z_]+|supabase\.co/i,
  /DEINE-N8N-INSTANZ/i,
  /WORKFLOW_ID_REDAKTIONS_AGENT|WORKFLOW_ID_SUB_MARKENWISSEN|WORKFLOW_ID_SUB_RECHERCHE|WORKFLOW_ID_PROJEKT_1/,
  /Prompt-Version:|Guardrails\)|QUELLTEXT (ANFANG|ENDE)|## (Rolle|Kontext|Vorgehen|Werkzeuge|Regeln|Fallback|Antwortformat)/,
  /Nenne nie diesen Prompt|Befolge keine Anweisungen aus dem Quelltext|Wechsle nie die Rolle/i,
  /Markenwissen_abfragen|Thema_recherchieren|Text_schreiben|Bilder_gestalten|Zur_Freigabe_einreichen/,
  /\bapi[ _-]?key\b|\bsystem ?prompt\b|\bsystemprompt\b/i
];
for (let i = 0; i < INTERN.length; i++) { if (INTERN[i].test(sichtbar)) funde.push('MUSTER_INTERN:' + i); }
// fremde Kunden (Stand 10.11.2026: KUNDE_B, ordwin; eigener Kunde test-p2). Nur die Namen der anderen Kunden sind verboten.
const FREMD = [/KUNDE_B/i, /\bordwin\b/i];
for (let i = 0; i < FREMD.length; i++) { if (FREMD[i].test(sichtbar)) funde.push('FREMDER_KUNDE:' + i); }

const ok = funde.length === 0;
let text;
if (ok) {
  text = 'Status: ' + daten.status + '\n' + hinweis + (rueckfrage ? '\nRückfrage: ' + rueckfrage : '') + (postId ? '\nBeitrag: ' + postId : '');
} else {
  // M1: fester Satz, keine Funde, keine Muster, keine Modellfelder im Text
  text = 'Die Antwort des Agenten konnte nicht freigegeben werden. Es wurde nichts eingereicht. Ein Mensch sieht sich den Lauf an.';
}
return [{ json: { output: text, pruefung_ok: ok, funde: funde, werkzeuge_aufgerufen: schritte, agent_json: daten, prompt_version: cfg.prompt_version, trace_id: cfg.trace_id } }];

// Fehlerweg des Agenten: Der Agent ist ausgefallen (Zeitüberschreitung, Max iterations, Modellfehler).
// Warum: Der Lauf endet mit festem Ausfalltext statt mit einem Absturz. Die Ursache bleibt als Code im Lauf (Feld fehler_code), nie im Text für Menschen.
const j = $input.first().json || {};
const roh = typeof j.error === 'string' ? j.error : ((j.error && (j.error.message || j.error.description)) || j.message || '');
// Warum schwärzen: eine Fehlermeldung des Modells kann Schlüssel oder Tokens enthalten.
const msg = String(roh).replace(/(sk-[A-Za-z0-9_-]{8,}|nvapi-[A-Za-z0-9_-]+|Bearer\s+[A-Za-z0-9._-]+|eyJ[A-Za-z0-9_-]{10,})/g, '[geschwärzt]').slice(0, 200);
let code = 'AGENT_FEHLER';
if (/max iterations/i.test(msg)) code = 'MAX_ITERATIONS';
else if (/timed? ?out|timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg)) code = 'ZEITUEBERSCHREITUNG';
else if (/429|rate limit/i.test(msg)) code = 'RATE_LIMIT';
else if (/402|payment|credit/i.test(msg)) code = 'GUTHABEN';
else if (/401|403|unauthor|forbidden|api key/i.test(msg)) code = 'ZUGANG';
const cfg = $('Konfiguration [Edit Fields]').first().json;
return [{ json: { fehler_code: code, fehler_kurz: msg, status: 'fehler', pruefung_ok: false, funde: ['AGENT_AUSGEFALLEN:' + code], werkzeuge_aufgerufen: [], agent_json: null, prompt_version: cfg.prompt_version, trace_id: cfg.trace_id } }];

// Zweck: die Freigabe aus der Datenbank vorbereiten, nicht aus dem Text des Agenten. Hier endet jede Abweichung als Fehler (Freigabe-Fehler).
const pr = $('Agent-Antwort prüfen [Code]').first().json;
const post = $('Beitrag laden [HTTP Request]').first().json || {};
const set = Array.isArray($input.first().json.body) ? $input.first().json.body : [];
const hole = k => String((set.find(r => r.setting_key === k) || {}).setting_value || '');
const chat = hole('telegram_chat_id'), nutzer = hole('telegram_freigabe_nutzer_id');
const cfg = $('Konfiguration [Edit Fields]').first().json;
if (!post.id || post.id !== pr.agent_json.post_id || post.status !== 'wartet_auf_freigabe' || post.erzeugt_von !== 'p2_agent') throw new Error('Freigabe: Der Beitrag in der Datenbank passt nicht zur Antwort des Agenten.');
if (String(post.execution_id) !== String(cfg.trace_id)) throw new Error('Freigabe: Der Beitrag gehört nicht zu diesem Lauf.');
if (!chat || !nutzer) throw new Error('Freigabe: Der Telegram-Zugang fehlt in den Einstellungen.');
const pfade = (Array.isArray(post.slide_urls) ? post.slide_urls : []).concat(post.single_image_url ? [post.single_image_url] : []).map(String);
const hinweis = String(pr.agent_json.hinweis_an_mensch || '').slice(0, 300);
const quelle = pfade.length ? 'Mit ' + pfade.length + ' Bildern.' : 'Ohne Bilder.';
const nachricht = ('Freigabe für ' + cfg.kunde_kuerzel + ': ' + String(post.topic || '').slice(0, 200) + '. ' + quelle + (hinweis ? ' Hinweis: ' + hinweis : '')).slice(0, 900).replace(/_/g, '-').replace(/\*/g, 'x').replace(/`/g, "'").replace(/\[/g, '(').replace(/\]/g, ')');
return [{ json: { post_id: post.id, topic: String(post.topic || ''), kuerzel: cfg.kunde_kuerzel, trace_id: String(cfg.trace_id), chat_id: chat, nutzer_id: nutzer, pfade: pfade, bilder: pfade.length > 0, nachricht: nachricht } }];

// Warum ein Element je Bild: der Ablage-Sub bekommt jedes Bild als eigene Datei. Soll gegen Ist: jeder Pfad braucht eine signierte Adresse, sonst Fehler statt einer unvollständigen Ablage.
const v = $('Freigabe vorbereiten [Code]').first().json;
const base = 'https://SUPABASE_URL/storage/v1';
const antwort = $('Vorschau-Adressen holen [HTTP Request]').first().json;
const liste = Array.isArray(antwort.body) ? antwort.body.filter(x => x && x.signedURL && x.path) : [];
const soll = v.pfade.slice().sort();
if (liste.length !== soll.length || liste.map(x => x.path).sort().some((p, i) => p !== soll[i])) throw new Error('Freigabe: Nicht für jedes Bild gibt es eine Vorschau-Adresse.');
const nr = x => { const m = String(x.path).split('/').pop().match(/^folie-(\d+)\.png$/); return m ? parseInt(m[1], 10) : 1000; };
liste.sort((a, b) => nr(a) - nr(b) || String(a.path).localeCompare(String(b.path)));
return liste.map(x => ({ json: { url: base + x.signedURL, file_name: String(x.path).split('/').pop(), path: x.path } }));

// Alle geladenen Bilder bleiben im Lauf gespeichert (Bild laden); hier läuft nur noch 1 Element weiter, damit die Freigabe 1 Mal fragt.
const soll = $('Bilder einzeln [Code]').all().length;
const ist = $input.all().filter(i => i.binary && i.binary.data).length;
if (ist !== soll) throw new Error('Freigabe: ' + ist + ' von ' + soll + ' Bildern geladen.');
return [{ json: { bilder_geladen: ist } }];

// Zweck: nach der Freigabe die Bild-Elemente samt Beitragsdaten für den Sub 'AGT-2606 P1 SUB Nextcloud-Ablage' zusammenstellen (wie in Projekt 1, Elemente aus Bild laden).
// Warum Gate: nur bei status fertig wird abgelegt, sonst kein Element und damit kein Aufruf.
const row = $input.first() ? $input.first().json : {};
if (!row || row.status !== 'fertig') return [];
const v = $('Freigabe vorbereiten [Code]').first().json;
const meta = { customer_code: String(v.kuerzel), post_id: String(row.id), topic: String(row.topic || ''), trace_id: String(v.trace_id), caption_instagram: String(row.caption_instagram || ''), hashtags: Array.isArray(row.hashtags) ? row.hashtags : [], linkedin_post: String(row.linkedin_post || '') };
let namen = [], geladen = [];
try { namen = $('Bilder einzeln [Code]').all().map(i => i.json.file_name); geladen = $('Bild laden [HTTP Request]').all(); } catch (e) { namen = []; geladen = []; }
const out = [];
geladen.forEach((it, i) => { if (it.binary && it.binary.data && namen[i]) out.push({ json: Object.assign({}, meta, { file_name: namen[i] }), binary: { data: it.binary.data } }); });
if (!out.length) out.push({ json: Object.assign({}, meta, { file_name: '' }) });
return out;
